  out.innerHTML = stats([['Average latency', nf(w(V.u), 0) + ' ms'], ['p99 latency', nf(w(V.u) * Math.log(100), 0) + ' ms'], ['vs. idle', nf(w(V.u) / V.s, 1) + '×']]) + '<div class="wg-g"></div>';
  chart(out.querySelector('.wg-g'), {xs, ymin: 0, ymax: w(98) * Math.log(100) / 4, zones: [{x0: 10, x1: 70, c: 'var(--go)', t: 'comfortable'}, {x0: 70, x1: 85, c: 'var(--gold)', t: 'queues build'}, {x0: 85, x1: 98, c: 'var(--bad)', t: 'overload'}], area: true, series: [{n: 'p99', c: 'var(--c2)', ys: xs.map(u => w(u) * Math.log(100))}, {n: 'Average', c: 'var(--c1)', ys: xs.map(w)}], xf: v => v + '%', yf: v => nf(v) + ' ms', xn: 'Load', xl: 'Utilisation', yl: 'Latency', mark: {x: V.u, t: V.u + '% busy'}, aria: 'Latency stays flat at low load and shoots up as utilisation nears 100%.'});
