WG.ring = el => {
  el.innerHTML = '<div class="wg-c"><label class="wg-s"><span>Virtual nodes per server <output></output></span><input type="range" min="1" max="100" value="1" data-id="v"></label><div class="wg-btns"><button type="button" class="btn ghost sm" data-a="rm">− Remove server</button><button type="button" class="btn ghost sm" data-a="add">+ Add server</button></div></div><div class="wg-o"></div>';
  let N = 4, prev = null, moved = null, modMoved = null; const K = [...Array(400)].map((_, i) => fnv('key:' + i));
  const own = (n, v) => { const pts = []; for (let s = 0; s < n; s++) for (let j = 0; j < v; j++) pts.push([fnv(`server-${s}#${j}`), s]); pts.sort((a, b) => a[0] - b[0]);
    return {pts, a: K.map(k => { const p = pts.find(q => q[0] >= k) || pts[0]; return p[1]; })}; };
  const draw = () => {
    const v = +el.querySelector('[data-id="v"]').value; el.querySelector('output').textContent = v;
    const {pts, a} = own(N, v), load = Array(N).fill(0); a.forEach(s => load[s]++);
    if (prev && prev.n !== N && prev.v === v){ moved = a.filter((s, i) => s !== prev.a[i]).length; const m1 = K.map(k => Math.floor(k * 4294967296) % prev.n), m2 = K.map(k => Math.floor(k * 4294967296) % N); modMoved = m1.filter((s, i) => s !== m2[i]).length; } else if (prev && prev.v !== v){ moved = null; }
    prev = {a, n: N, v};
    const R = 100, C = 130, P = t => [C + R * Math.sin(t * 2 * Math.PI), C - R * Math.cos(t * 2 * Math.PI)];
    let g = `<circle cx="${C}" cy="${C}" r="${R}" fill="none" stroke="var(--line2)" stroke-width="10"/>`;
    K.forEach((k, i) => { const [x, y] = P(k); g += `<circle cx="${x}" cy="${y}" r="2.6" fill="${CAT(a[i])}"/>`; });
    pts.forEach(([t, s]) => { const [x, y] = P(t), [x2, y2] = [C + (R + 16) * Math.sin(t * 2 * Math.PI), C - (R + 16) * Math.cos(t * 2 * Math.PI)];
      g += v <= 3 ? `<rect x="${x2 - 8}" y="${y2 - 8}" width="16" height="16" rx="4" fill="${CAT(s)}" stroke="var(--card)" stroke-width="2"/><text x="${x2}" y="${y2 + 4}" text-anchor="middle" font-size="9.5" font-weight="700" fill="#fff">${s + 1}</text>` : `<line x1="${x}" y1="${y}" x2="${x2}" y2="${y2}" stroke="${CAT(s)}" stroke-width="2"/>`; });
    const fair = K.length / N, mx = Math.max(...load);
    const bars = load.map((l, s) => `<div class="rb"><span>Server ${s + 1}</span><i style="width:${l / mx * 100}%;background:${CAT(s)}"></i><b>${nf(l / K.length * 100, 0)}%</b></div>`).join('');
    el.querySelector('.wg-o').innerHTML = stats([['Busiest server', nf(mx / fair, 2) + '× its fair share'], ['Keys moved by last change', moved == null ? 'add or remove a server' : `${pct(moved / K.length, 0)}`, moved == null ? '' : `hash % N would move ${pct(modMoved / K.length, 0)}`]]) +
      `<div class="hring"><svg viewBox="0 0 260 260" role="img" aria-label="Hash ring with ${N} servers and ${v} virtual nodes each; dots are keys coloured by owner">${g}</svg><div class="rbars">${bars}</div></div>`;
    el.querySelector('[data-a="rm"]').disabled = N <= 2; el.querySelector('[data-a="add"]').disabled = N >= 8;
  };
  el.querySelector('input').addEventListener('input', draw);
  el.querySelector('.wg-btns').onclick = e => { const b = e.target.closest('button'); if (!b) return; N += b.dataset.a === 'add' ? 1 : -1; N = Math.max(2, Math.min(8, N)); draw(); };
  draw();
};

WG.bloom = el => {
  el.innerHTML = '<div class="wg-x"></div><div class="wg-sub"><div class="lab">Try a tiny filter: 32 bits, 3 hash functions</div><div class="bf-in"><input type="text" maxlength="24" placeholder="type a word" aria-label="Word"><button type="button" class="btn sm" data-a="add">Add</button><button type="button" class="btn ghost sm" data-a="chk">Check</button></div><div class="bf-bits"></div><p class="bf-msg" aria-live="polite">Add a few words, then check some you didn\'t add.</p></div>';
  controls(el.querySelector('.wg-x'), [
    {id: 'b', label: 'Bits per item (m/n)', min: 2, max: 20, v: 10},
    {id: 'k', label: 'Hash functions (k)', min: 1, max: 15, v: 7}
  ], (V, out) => {
    const fp = (b, k) => Math.pow(1 - Math.exp(-k / b), k), xs = [...Array(15)].map((_, i) => i + 1), ko = Math.max(1, Math.round(V.b * Math.LN2));
    const B = [4, 6, 8, 10, 12, 14, 16, 20], K = [1, 2, 3, 4, 5, 6, 7, 8, 10, 12], sh = v => { const r = Math.min(1, Math.max(0, (Math.log10(v) + 6) / 6)); return `color-mix(in oklab, var(--c1) ${Math.round(8 + r * 92)}%, var(--card))`; }, lab = v => v >= 0.01 ? nf(v * 100, 0) + '%' : v >= 0.001 ? (v * 100).toFixed(1) + '%' : (v * 100).toFixed(2) + '%';
    out.innerHTML = stats([['False positive rate', pct(fp(V.b, V.k), fp(V.b, V.k) < 0.001 ? 3 : 2)], ['Best k for this size', ko, pct(fp(V.b, ko), 2)], ['Memory for 1 billion items', nf(V.b * 1e9 / 8 / 1e9, 2) + ' GB']]) +
      `<div class="lab" style="margin:4px 0 8px">False positive rate: bits per item (rows) × hash functions (columns). Darker is worse; ● marks the best k per row. Tap a cell.</div><div class="bhm" style="--cols:${K.length}"><span></span>${K.map(k => `<span class="bhm-h">k=${k}</span>`).join('')}${B.map(b => { const kb = Math.max(1, Math.round(b * Math.LN2)); return `<span class="bhm-h">${b} bits</span>` + K.map(k => { const v = fp(b, k), on = b === V.b && k === V.k; return `<button type="button" class="bhm-c${on ? ' on' : ''}" data-b="${b}" data-k="${k}" style="background:${sh(v)};color:${v > 0.02 ? '#fff' : 'var(--ink)'}" title="${b} bits, k=${k}: ${pct(v, 3)}">${lab(v)}${Math.abs(k - kb) < 0.5 || (kb > 8 && k === K.reduce((a, c) => Math.abs(c - kb) < Math.abs(a - kb) ? c : a)) ? '<em>●</em>' : ''}</button>`; }).join(''); }).join('')}</div>`;
    out.querySelector('.bhm').onclick = e => { const c = e.target.closest('.bhm-c'); if (!c) return; const x = el.querySelector('.wg-x'); x.querySelector('[data-id="b"]').value = c.dataset.b; x.querySelector('[data-id="k"]').value = c.dataset.k; x.querySelector('[data-id="b"]').dispatchEvent(new Event('input', {bubbles: true})); };
  });
  const bits = Array(32).fill(0), added = new Set(), bx = el.querySelector('.bf-bits'), msg = el.querySelector('.bf-msg'), inp = el.querySelector('.bf-in input');
  const hs = w => [1, 2, 3].map(i => Math.floor(fnv(i + ':' + w.toLowerCase()) * 32));
  const paint = (hl = [], ok) => { bx.innerHTML = bits.map((b, i) => `<span class="${b ? 'on' : ''}${hl.includes(i) ? (ok ? ' hl' : ' miss') : ''}">${i}</span>`).join(''); };
  el.querySelector('.bf-in').onclick = e => { const b = e.target.closest('button'), w = inp.value.trim(); if (!b || !w) return; const h = hs(w);
    if (b.dataset.a === 'add'){ h.forEach(i => bits[i] = 1); added.add(w.toLowerCase()); paint(h, true); msg.innerHTML = `Added <b>${esc(w)}</b>: set bits ${h.join(', ')}.`; inp.value = ''; }
    else { const all = h.every(i => bits[i]); paint(h, all); msg.innerHTML = !all ? `<b>${esc(w)}</b>: definitely not added (bit ${h.find(i => !bits[i])} is 0).` : added.has(w.toLowerCase()) ? `<b>${esc(w)}</b>: maybe present (all 3 bits set). It was added.` : `<b>${esc(w)}</b>: maybe present, but you never added it. That's a false positive.`; } };
  inp.addEventListener('keydown', e => { if (e.key === 'Enter') el.querySelector('[data-a="add"]').click(); });
  paint();
};

WG.lru = el => {
  el.innerHTML = '<div class="wg-c"><label class="wg-s"><span>Policy</span><select data-id="p"><option value="LRU">LRU</option><option value="LFU">LFU</option><option value="FIFO">FIFO</option></select></label><label class="wg-s"><span>Capacity <output>3</output></span><input type="range" min="2" max="6" value="3" data-id="c"></label></div><div class="lru-keys" role="group" aria-label="Request a key">' + 'ABCDEF'.split('').map(k => `<button type="button" class="btn ghost sm" data-k="${k}">${k}</button>`).join('') + '</div><div class="wg-btns"><button type="button" class="btn ghost sm" data-a="hot">30 skewed requests</button><button type="button" class="btn ghost sm" data-a="scan">One-off scan (G to N)</button><button type="button" class="btn ghost sm" data-a="reset">Reset</button></div><div class="wg-o"></div>';
  let S, hits, miss, last; const R = rng(3);
  const reset = () => { S = []; hits = 0; miss = 0; last = 'Request keys and watch what gets evicted.'; };
  const pol = () => el.querySelector('[data-id="p"]').value, cap = () => +el.querySelector('[data-id="c"]').value;
  const victim = () => { const p = pol(); if (p === 'FIFO') return S.reduce((a, b) => a.ins < b.ins ? a : b); if (p === 'LRU') return S.reduce((a, b) => a.used < b.used ? a : b); return S.reduce((a, b) => (a.n < b.n || (a.n === b.n && a.used < b.used)) ? a : b); };
  let clock = 0;
  const req = (k, quiet) => { clock++; const e = S.find(x => x.k === k);
    if (e){ e.used = clock; e.n++; hits++; if (!quiet) last = `<b>${k}</b>: hit`; return; }
    miss++; let ev = ''; while (S.length >= cap()){ const v = victim(); S = S.filter(x => x !== v); ev = v.k; }
    S.push({k, ins: clock, used: clock, n: 1}); if (!quiet) last = `<b>${k}</b>: miss${ev ? `, evicted <b>${ev}</b>` : ''}`; };
  const draw = () => { el.querySelector('output').textContent = cap(); while (S.length > cap()){ const v = victim(); S = S.filter(x => x !== v); }
    const v = S.length >= cap() ? victim() : null, p = pol();
    const ord = [...S].sort((a, b) => p === 'FIFO' ? b.ins - a.ins : p === 'LRU' ? b.used - a.used : (b.n - a.n) || (b.used - a.used));
    el.querySelector('.wg-o').innerHTML = stats([['Hit rate', hits + miss ? pct(hits / (hits + miss), 0) : '–', `${hits} hits, ${miss} misses`]]) +
      `<div class="lru-row" aria-label="Cache contents">${[...Array(cap())].map((_, i) => { const e = ord[i]; return e ? `<div class="slot${e === v ? ' ev' : ''}"><b>${e.k}</b><small>${p === 'LFU' ? e.n + '× used' : p === 'LRU' ? 'used t' + e.used : 'in at t' + e.ins}</small>${e === v ? '<em>evicted next</em>' : ''}</div>` : '<div class="slot empty">empty</div>'; }).join('')}</div><p class="bf-msg" aria-live="polite">${last}</p>`; };
  el.addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return;
    if (b.dataset.k) req(b.dataset.k);
    else if (b.dataset.a === 'hot'){ for (let i = 0; i < 30; i++){ const r = R(); req(r < .45 ? 'A' : r < .7 ? 'B' : r < .85 ? 'C' : 'DEF'[Math.floor(R() * 3)], true); } last = 'Ran 30 requests where A, B and C are popular.'; }
    else if (b.dataset.a === 'scan'){ 'GHIJKLMN'.split('').forEach(k => req(k, true)); last = 'A one-off scan of G to N. Under LRU it flushes the popular keys; LFU keeps them.'; }
    else if (b.dataset.a === 'reset') reset();
    else return; draw(); });
  el.querySelector('.wg-c').addEventListener('input', draw); reset(); draw();
};

WG.amp = el => controls(el, [
  {id: 't', label: 'Size ratio between levels (T)', min: 2, max: 20, v: 10},
  {id: 'd', label: 'Data size', opts: [[10, '10 GB'], [100, '100 GB'], [1000, '1 TB'], [10000, '10 TB']], v: 1000}
], (V, out) => {
  const L = Math.max(1, Math.ceil(Math.log(V.d / 0.256) / Math.log(V.t)));
  const M = [['Write amplification', V.t * L / 2, L, 'bytes rewritten per byte written'], ['Read amplification', L, V.t * L / 2, 'sorted runs a lookup may check'], ['Space amplification', 1 + 1 / V.t, 2, 'disk used ÷ live data']];
  out.innerHTML = stats([['Levels', L, 'with a 256 MB first level']]) + `<div class="wg-lg"><span><i style="background:var(--c1)"></i>Leveled</span><span><i style="background:var(--c2)"></i>Tiered</span></div><div class="amp">${M.map(([n, a, b, s]) => { const mx = Math.max(a, b);
    return `<div class="amp-p"><div class="lab">${n}</div><div class="amp-b"><div><i style="height:${a / mx * 100}%;background:var(--c1)"></i><b>${nf(a, a < 10 ? 1 : 0)}×</b></div><div><i style="height:${b / mx * 100}%;background:var(--c2)"></i><b>${nf(b, b < 10 ? 1 : 0)}×</b></div></div><small>${s}</small></div>`; }).join('')}</div>`;
});

WG.bm25 = el => controls(el, [
  {id: 'k', label: 'k1', min: 0.2, max: 3, step: 0.1, v: 1.2, f: v => v.toFixed(1)},
  {id: 'b', label: 'b', min: 0, max: 1, step: 0.05, v: 0.75, f: v => v.toFixed(2)},
  {id: 'l', label: 'This document\'s length vs average', min: -2, max: 2, step: 0.25, v: 1, f: v => nf(Math.pow(2, v), 2) + '×'}
], (V, out) => {
  const xs = [...Array(21)].map((_, i) => i), r = Math.pow(2, V.l), f = (tf, len) => tf * (V.k + 1) / (tf + V.k * (1 - V.b + V.b * len));
  out.innerHTML = stats([['Score at tf = 3', nf(f(3, r), 2)], ['Ceiling (k1 + 1)', nf(V.k + 1, 1)]]) + '<div class="wg-g"></div>';
  chart(out.querySelector('.wg-g'), {xs, ymin: 0, ymax: V.k + 1.3, series: [{n: `This document (${nf(r, 2)}× average length)`, c: 'var(--c1)', ys: xs.map(t => f(t, r))}, {n: 'Average-length document', c: 'var(--c2)', ys: xs.map(t => f(t, 1))}], hline: {y: V.k + 1, t: 'limit k1 + 1'}, xf: v => nf(v), yf: v => nf(v, 2), xn: 'tf =', xl: 'Times the term appears (tf)', yl: 'BM25 term-frequency part', mark: {x: 3, t: 'tf = 3'}, aria: 'BM25 term frequency saturates: each extra occurrence adds less, up to k1 + 1.'});
});

WG.hll = el => {
  const NV = v => Math.round(Math.pow(10, v / 10));
  controls(el, [
    {id: 'p', label: 'Precision p (registers = 2ᵖ)', min: 4, max: 16, v: 14, f: v => `${v} → ${nf(Math.pow(2, v))}`},
    {id: 'n', label: 'Distinct items actually added', min: 20, max: 60, v: 50, f: v => nf(NV(v))}
  ], (V, out) => {
    const m = 1 << V.p, n = NV(V.n), reg = new Uint8Array(m), R = rng(V.p * 1000 + V.n);
    for (let i = 0; i < n; i++){ const h = (R() * 4294967296) >>> 0, idx = h >>> (32 - V.p), w = (h << V.p) >>> 0; const rho = w === 0 ? 33 - V.p : Math.clz32(w) + 1; if (rho > reg[idx]) reg[idx] = rho; }
    let s = 0, z = 0; for (let i = 0; i < m; i++){ s += Math.pow(2, -reg[i]); if (!reg[i]) z++; }
    const al = m === 16 ? 0.673 : m === 32 ? 0.697 : m === 64 ? 0.709 : 0.7213 / (1 + 1.079 / m); let E = al * m * m / s; if (E <= 2.5 * m && z) E = m * Math.log(m / z);
    const se = 1.04 / Math.sqrt(m), mem = m * 6 / 8, mf = b => b < 1024 ? nf(b) + ' B' : nf(b / 1024, b < 10240 ? 1 : 0) + ' KB';
    const T = 40, nt = Math.min(n, 20000), errs = [...Array(T)].map((_, t) => { const r = new Uint8Array(m), Rr = rng(t * 7919 + V.p); for (let i = 0; i < nt; i++){ const h = (Rr() * 4294967296) >>> 0, ix = h >>> (32 - V.p), w = (h << V.p) >>> 0, rho = w === 0 ? 33 - V.p : Math.clz32(w) + 1; if (rho > r[ix]) r[ix] = rho; }
      let s2 = 0, z2 = 0; for (let i = 0; i < m; i++){ s2 += Math.pow(2, -r[i]); if (!r[i]) z2++; } let e = al * m * m / s2; if (e <= 2.5 * m && z2) e = m * Math.log(m / z2); return (e - nt) / nt; });
    const lim = Math.max(3 * se, ...errs.map(Math.abs)) * 1.1, W = 640, H = 220, ml = 54, pw = W - ml - 14, sy = v => 14 + (1 - (v + lim) / (2 * lim)) * (H - 40), within = errs.filter(e => Math.abs(e) <= se).length;
    out.innerHTML = stats([['Estimate', nf(E), 'true count ' + nf(n)], ['Error this run', (E >= n ? '+' : '−') + pct(Math.abs(E - n) / n, 2)], ['Memory', mf(mem), 'vs ' + mf(n * 8) + ' for 8-byte IDs']]) +
      `<div class="lab" style="margin:4px 0 8px">40 repeated runs with ${nf(nt)} items: error of each run. Shaded band = ±1 standard error (1.04/√m = ${pct(se, 2)}); ${within} of 40 runs land inside it.</div><div class="wg-ch"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Scatter of HyperLogLog errors across 40 runs, mostly inside plus or minus one standard error">
      <rect x="${ml}" y="${sy(se)}" width="${pw}" height="${sy(-se) - sy(se)}" fill="var(--c1)" opacity=".12"/><line x1="${ml}" x2="${ml + pw}" y1="${sy(0)}" y2="${sy(0)}" stroke="var(--line2)"/>
      ${[-2 * se, -se, 0, se, 2 * se].filter(v => Math.abs(v) < lim).map(v => `<text x="${ml - 8}" y="${sy(v) + 4}" text-anchor="end" font-size="11" fill="var(--muted)">${v > 0 ? '+' : v < 0 ? '−' : ''}${pct(Math.abs(v), 1)}</text>`).join('')}
      ${[2 * se, -2 * se].map(v => `<line x1="${ml}" x2="${ml + pw}" y1="${sy(v)}" y2="${sy(v)}" stroke="var(--c1)" stroke-dasharray="4 4" opacity=".5"/>`).join('')}
      ${errs.map((e, i) => `<circle cx="${ml + (i + .5) / T * pw}" cy="${sy(e)}" r="5" fill="${Math.abs(e) <= se ? 'var(--c1)' : 'var(--c2)'}" stroke="var(--card)" stroke-width="1.5"><title>Run ${i + 1}: ${e >= 0 ? '+' : '−'}${pct(Math.abs(e), 2)}</title></circle>`).join('')}
      <text x="${ml + pw / 2}" y="${H - 6}" text-anchor="middle" font-size="11" fill="var(--muted)">Run 1 to 40</text></svg></div>`;
  });
};

WG.geohash = el => {
  const B32 = '0123456789bcdefghjkmnpqrstuvwxyz', PT = {n: 'Example point (central London)', lat: 51.5074, lng: -0.1278};
  let h = '';
  const box = s => { let a = [-90, 90], o = [-180, 180], ev = true; for (const ch of s){ const v = B32.indexOf(ch); for (let b = 4; b >= 0; b--){ const bit = v >> b & 1, r = ev ? o : a, mid = (r[0] + r[1]) / 2; if (bit) r[0] = mid; else r[1] = mid; ev = !ev; } } return {a, o}; };
  const enc = (lat, lng, n) => { let s = ''; for (let i = 0; i < n; i++){ for (const ch of B32){ const b = box(s + ch); if (lat >= b.a[0] && lat < b.a[1] && lng >= b.o[0] && lng < b.o[1]){ s += ch; break; } } } return s; };
  el.innerHTML = '<div class="gh-bar"><button type="button" class="btn ghost sm" data-a="up">← Zoom out</button><button type="button" class="btn ghost sm" data-a="pt">Follow the example point</button></div><div class="wg-o"></div>';
  const draw = () => {
    const b = box(h), even = h.length % 2 === 0, cols = even ? 8 : 4, rows = even ? 4 : 8, dw = b.o[1] - b.o[0], dh = b.a[1] - b.a[0];
    const W = 600, H = Math.round(Math.min(380, Math.max(220, W * dh / dw))), cw = W / cols, chh = H / rows, ptc = enc(PT.lat, PT.lng, h.length + 1);
    let g = '';
    for (const ch of B32){ const c = box(h + ch), x = (c.o[0] - b.o[0]) / dw * W, y = (b.a[1] - c.a[1]) / dh * H, hot = ptc === h + ch;
      g += `<g class="gh-c${hot ? ' hot' : ''}" data-c="${ch}" tabindex="0" role="button" aria-label="Zoom into ${h + ch}"><rect x="${x + 1}" y="${y + 1}" width="${cw - 2}" height="${chh - 2}" rx="4"/><text x="${x + cw / 2}" y="${y + chh / 2 + 5}" text-anchor="middle" font-size="${Math.min(15, cw / 2.4)}">${ch}</text></g>`; }
    const inside = PT.lat >= b.a[0] && PT.lat < b.a[1] && PT.lng >= b.o[0] && PT.lng < b.o[1];
    if (inside) g += `<circle cx="${(PT.lng - b.o[0]) / dw * W}" cy="${(b.a[1] - PT.lat) / dh * H}" r="5" fill="var(--c2)" stroke="var(--card)" stroke-width="2" pointer-events="none"/>`;
    const km = (b.a[0] + b.a[1]) / 2, wkm = dw / cols * 111.32 * Math.cos(km * Math.PI / 180), hkm = dh / rows * 110.57, kf = v => v >= 10 ? nf(v) + ' km' : v >= 1 ? nf(v, 1) + ' km' : nf(v * 1000) + ' m';
    el.querySelector('.wg-o').innerHTML = stats([['Current prefix', h ? `<code>${h}</code>` : 'whole world'], ['Each cell below', `${kf(wkm)} × ${kf(hkm)}`, `${h.length + 1} character${h.length ? 's' : ''}`], ['Example point', `<code>${enc(PT.lat, PT.lng, Math.max(6, h.length + 1))}</code>`, 'orange dot when in view']]) +
      `<div class="wg-ch"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Geohash cells for prefix ${h || 'none'}; tap a cell to zoom in">${g}</svg></div>`;
    el.querySelector('[data-a="up"]').disabled = !h; el.querySelector('[data-a="pt"]').disabled = h.length >= 8;
  };
  el.addEventListener('click', e => { const c = e.target.closest('.gh-c'), b = e.target.closest('button');
    if (c && h.length < 8){ h += c.dataset.c; draw(); } else if (b?.dataset.a === 'up'){ h = h.slice(0, -1); draw(); } else if (b?.dataset.a === 'pt' && h.length < 8){ h = enc(PT.lat, PT.lng, h.length + 1); draw(); } });
  el.addEventListener('keydown', e => { const c = e.target.closest('.gh-c'); if (c && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); c.dispatchEvent(new MouseEvent('click', {bubbles: true})); } });
  draw();
};

WG.bucket = el => {
  el.innerHTML = '<div class="wg-x"></div><div class="wg-btns"><button type="button" class="btn sm" data-a="run">Start</button><button type="button" class="btn ghost sm" data-a="burst">Send a burst of 15</button></div><div class="bk-o"></div>';
  let tok = 10, hist = [], acc = 0, rej = 0, t = 0, timer = null, pend = 0, V; const R = rng(11), TK = 100, KEEP = 150;
  const cv = controls(el.querySelector('.wg-x'), [
    {id: 'c', label: 'Bucket capacity', min: 1, max: 20, v: 10, f: v => v + ' tokens'},
    {id: 'r', label: 'Refill rate', min: 1, max: 10, v: 3, f: v => v + ' per second'},
    {id: 'q', label: 'Traffic', opts: [[0, 'Quiet (1/s)'], [1, 'Steady (5/s)'], [2, 'Spiky']], v: 1}
  ], v => { V = v; tok = Math.min(tok, V.c); });
  const step = () => { t++; tok = Math.min(V.c, tok + V.r * TK / 1000);
    const rate = V.q === 0 ? 1 : V.q === 1 ? 5 : (Math.floor(t / 20) % 4 === 0 ? 18 : 1);
    let n = pend + (R() < rate * TK / 1000 ? 1 : 0) + (rate * TK / 1000 > 1 ? Math.floor(rate * TK / 1000) : 0); pend = 0;
    let a = 0, r = 0; while (n-- > 0){ if (tok >= 1){ tok -= 1; a++; } else r++; } acc += a; rej += r; hist.push({tok, a, r}); if (hist.length > KEEP) hist.shift(); };
  const draw = () => { const NW = el.clientWidth < 520, W = NW ? 420 : 640, H = 210, m = {l: 40, r: 10, t: 12, b: 42}, pw = W - m.l - m.r, ph = H - m.t - m.b, dx = pw / KEEP, sy = v => m.t + ph - v / V.c * ph;
    let g = ticks(0, V.c).map(v => `<line x1="${m.l}" x2="${W - m.r}" y1="${sy(v)}" y2="${sy(v)}" stroke="var(--line)"/><text x="${m.l - 6}" y="${sy(v) + 4}" text-anchor="end" font-size="11" fill="var(--muted)">${v}</text>`).join('');
    const off = KEEP - hist.length;
    g += `<polyline points="${hist.map((h, i) => `${(m.l + (off + i) * dx).toFixed(1)},${sy(h.tok).toFixed(1)}`).join(' ')}" fill="none" stroke="var(--c1)" stroke-width="2"/>`;
    hist.forEach((h, i) => { const x = m.l + (off + i) * dx; for (let j = 0; j < h.a; j++) g += `<circle cx="${x}" cy="${H - m.b + 8 + j * 0}" r="2.6" fill="var(--go)"/>`; for (let j = 0; j < h.r; j++) g += `<rect x="${x - 2.5}" y="${H - m.b + 14 + Math.min(j, 3) * 0}" width="5" height="5" fill="var(--bad)"/>`; });
    el.querySelector('.bk-o').innerHTML = stats([['Tokens now', nf(tok, 1)], ['Allowed', nf(acc)], ['Rejected (429)', nf(rej)]]) + `<div class="wg-lg"><span><i style="background:var(--c1)"></i>Tokens in bucket</span><span><i style="background:var(--go);border-radius:50%;width:8px;height:8px"></i>Allowed</span><span><i style="background:var(--bad);width:7px;height:7px"></i>Rejected</span></div><div class="wg-ch"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Token level over the last 15 seconds with allowed and rejected requests">${g}<text x="${W - m.r}" y="${H - 2}" text-anchor="end" font-size="11" fill="var(--muted)">now</text><text x="${m.l}" y="${H - 2}" font-size="11" fill="var(--muted)">15 s ago</text></svg></div>`; };
  const run = () => { if (timer){ clearInterval(timer); timer = null; el.querySelector('[data-a="run"]').textContent = 'Start'; return; }
    el.querySelector('[data-a="run"]').textContent = 'Pause'; timer = setInterval(() => { if (!el.isConnected){ clearInterval(timer); return; } step(); draw(); }, TK); };
  el.querySelector('.wg-btns').onclick = e => { const b = e.target.closest('button'); if (!b) return; if (b.dataset.a === 'run') run(); else { pend += 15; if (!timer){ step(); draw(); } } };
  el.querySelector('.wg-x').addEventListener('input', draw);
  for (let i = 0; i < 60; i++) step(); draw();
};

WG.quorum = el => controls(el, [
  {id: 'n', label: 'Replicas (N)', min: 1, max: 7, v: 3},
  {id: 'w', label: 'Write waits for (W)', min: 1, max: 7, v: 2},
  {id: 'r', label: 'Read asks (R)', min: 1, max: 7, v: 2}
], (V, out) => {
  const N = V.n, W = Math.min(V.w, N), R = Math.min(V.r, N), ov = Math.max(0, W + R - N);
  const row = (lab, f) => `<div class="qr"><span class="lab">${lab}</span>${[...Array(N)].map((_, i) => `<i class="${f(i)}">${i + 1}</i>`).join('')}</div>`;
  out.innerHTML = stats([[ov ? 'Reads see the latest write' : 'Stale reads possible', ov ? `yes, ${ov} replica${ov > 1 ? 's' : ''} overlap` : 'no overlap', `W + R = ${W + R} ${ov ? '>' : '≤'} N = ${N}`], ['Writes keep working with', `${N - W} down`], ['Reads keep working with', `${N - R} down`]]) +
    `<div class="qbox">${row('Write acked by', i => i < W ? 'w' : '')}${row('Read asks', i => i >= N - R ? (i < W ? 'r both' : 'r') : '')}</div>` +
    (V.w > N || V.r > N ? `<p class="bf-msg">W and R can't exceed N, so they are capped at ${N}.</p>` : '');
});

function initFigs(root){
  root.querySelectorAll('figure.ix').forEach(f => { f.dataset.c = -1; });
  root.querySelectorAll('figure.wg').forEach(f => { const fn = WG[f.dataset.w], b = f.querySelector('.wg-b'); if (!fn){ b.textContent = 'Interactive figure unavailable.'; return; } try { fn(b); } catch (e){ console.error('widget', f.dataset.w, e); b.textContent = 'This interactive figure failed to load.'; } });
}


export { initFigs };
